#[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct OperationTransaction {
    pub operations: Vec<SemanticOperation>,
}

impl OperationTransaction {
    pub fn new(operations: Vec<SemanticOperation>) -> Result<Self, EngineError> {
        if operations.is_empty() || operations.len() > MAX_TRANSACTION_OPERATIONS {
            return Err(EngineError::InvalidTransaction(format!(
                "transaction operation count {} is outside 1..={MAX_TRANSACTION_OPERATIONS}",
                operations.len()
            )));
        }
        for operation in &operations {
            validate_operation_shape(operation)?;
        }
        Ok(Self { operations })
    }
}

fn validate_operation_shape(operation: &SemanticOperation) -> Result<(), EngineError> {
    let SemanticOperation::RenamePagesAndRewriteReferrers {
        page_changes,
        block_rewrites,
        page_preamble_rewrites,
    } = operation
    else {
        return Ok(());
    };
    if page_changes.is_empty() {
        return Err(EngineError::InvalidTransaction(
            "rename requires at least one page change".into(),
        ));
    }
    let entries = page_changes
        .len()
        .checked_add(block_rewrites.len())
        .and_then(|value| value.checked_add(page_preamble_rewrites.len()))
        .ok_or_else(|| EngineError::InvalidTransaction("rename entry count overflow".into()))?;
    if entries > super::semantic::MAX_SEMANTIC_DELTA_ENTRIES {
        return Err(EngineError::InvalidTransaction(format!(
            "rename entry count {entries} exceeds the semantic bound"
        )));
    }
    if !page_changes
        .windows(2)
        .all(|pair| pair[0].page_id < pair[1].page_id)
    {
        return Err(EngineError::InvalidTransaction(
            "rename page changes must be sorted and unique by page ID".into(),
        ));
    }
    if !block_rewrites.windows(2).all(|pair| {
        (pair[0].block.home_document_id, pair[0].block.block_id)
            < (pair[1].block.home_document_id, pair[1].block.block_id)
    }) {
        return Err(EngineError::InvalidTransaction(
            "rename block rewrites must be sorted and unique by home and block ID".into(),
        ));
    }
    if !page_preamble_rewrites
        .windows(2)
        .all(|pair| pair[0].page_id < pair[1].page_id)
    {
        return Err(EngineError::InvalidTransaction(
            "rename page-preamble rewrites must be sorted and unique by page ID".into(),
        ));
    }
    let mut bytes = 0_usize;
    for change in page_changes {
        bytes = bytes
            .checked_add(change.new_name.as_str().len())
            .and_then(|value| value.checked_add(change.new_path.as_str().len()))
            .ok_or_else(|| EngineError::InvalidTransaction("rename byte count overflow".into()))?;
    }
    for rewrite in block_rewrites {
        if rewrite.new_content.len() > super::semantic::MAX_BLOCK_CONTENT_BYTES {
            return Err(EngineError::InvalidTransaction(
                "rename block rewrite exceeds the semantic bound".into(),
            ));
        }
        bytes = bytes
            .checked_add(rewrite.new_content.len())
            .ok_or_else(|| EngineError::InvalidTransaction("rename byte count overflow".into()))?;
    }
    for rewrite in page_preamble_rewrites {
        if rewrite
            .new_preamble
            .as_ref()
            .is_some_and(|value| value.len() > super::semantic::MAX_PAGE_PREAMBLE_BYTES)
        {
            return Err(EngineError::InvalidTransaction(
                "rename page-preamble rewrite exceeds the semantic bound".into(),
            ));
        }
        bytes = bytes
            .checked_add(rewrite.new_preamble.as_ref().map_or(0, String::len))
            .ok_or_else(|| EngineError::InvalidTransaction("rename byte count overflow".into()))?;
    }
    if bytes > super::semantic::MAX_SEMANTIC_EFFECT_BYTES {
        return Err(EngineError::InvalidTransaction(format!(
            "rename payload size {bytes} exceeds the semantic bound"
        )));
    }
    let encoded_bytes = postcard::to_allocvec(operation)
        .map_err(|error| EngineError::InvalidTransaction(error.to_string()))?
        .len();
    if encoded_bytes > super::semantic::MAX_SEMANTIC_EFFECT_BYTES {
        return Err(EngineError::InvalidTransaction(format!(
            "encoded rename size {encoded_bytes} exceeds the semantic bound"
        )));
    }
    Ok(())
}

fn validate_logseq_identity_mutation_shape(
    transaction: &OperationTransaction,
) -> Result<(), EngineError> {
    let mut mutated_blocks = BTreeSet::new();
    for operation in &transaction.operations {
        let SemanticOperation::MutateBlockLogseqIdentity { block, .. } = operation else {
            continue;
        };
        if !mutated_blocks.insert(block.block_id) {
            return Err(EngineError::InvalidTransaction(format!(
                "block {} has more than one Logseq identity mutation",
                block.block_id
            )));
        }
    }
    Ok(())
}

fn operation_content_block(operation: &SemanticOperation) -> Option<BlockLocation> {
    match operation {
        SemanticOperation::CreateBlock { block, .. }
        | SemanticOperation::EditBlockContent { block, .. } => Some(*block),
        _ => None,
    }
}

fn content_has_logseq_trigger(
    content: &str,
    logseq_uuid: LogseqUuid,
    trigger: LogseqIdentityTrigger,
    is_org: bool,
) -> bool {
    let expected = logseq_uuid.to_string();
    let projection = crate::render::parse_projection(content, is_org);
    let mut found_reference = false;
    let mut found_embed = false;
    classify_logseq_triggers(
        &projection.blocks,
        &expected,
        is_org,
        &mut found_reference,
        &mut found_embed,
    );
    match trigger {
        LogseqIdentityTrigger::BlockReference { .. } => found_reference,
        LogseqIdentityTrigger::BlockEmbed { .. } => found_embed,
        LogseqIdentityTrigger::ExportUserAction
        | LogseqIdentityTrigger::CopiedDeepLinkUserAction => true,
    }
}

fn classify_logseq_triggers(
    blocks: &[lsdoc::ast::Block],
    expected: &str,
    is_org: bool,
    found_reference: &mut bool,
    found_embed: &mut bool,
) {
    use lsdoc::ast::Block;
    for block in blocks {
        match block {
            Block::Paragraph { inline, .. }
            | Block::Heading { inline, .. }
            | Block::Bullet { inline, .. }
            | Block::FootnoteDef { inline, .. } => {
                classify_logseq_inline_triggers(inline, expected, found_reference, found_embed);
            }
            Block::Quote { children, .. } | Block::Custom { children, .. } => {
                classify_logseq_triggers(children, expected, is_org, found_reference, found_embed);
            }
            Block::List { items, .. } => {
                for item in items {
                    classify_logseq_list_item_triggers(
                        item,
                        expected,
                        is_org,
                        found_reference,
                        found_embed,
                    );
                }
            }
            Block::Table { header, rows, .. } => {
                for cell in header
                    .iter()
                    .flat_map(|row| row.iter())
                    .chain(rows.iter().flat_map(|row| row.iter()))
                {
                    classify_logseq_inline_triggers(cell, expected, found_reference, found_embed);
                }
            }
            Block::Properties { props, .. } => {
                for property in props {
                    let projection =
                        lsdoc::parse_format(&property.1, if is_org { "org" } else { "md" });
                    classify_logseq_triggers(
                        &projection.blocks,
                        expected,
                        is_org,
                        found_reference,
                        found_embed,
                    );
                }
            }
            _ => {}
        }
    }
}

fn classify_logseq_list_item_triggers(
    item: &lsdoc::ast::ListItem,
    expected: &str,
    is_org: bool,
    found_reference: &mut bool,
    found_embed: &mut bool,
) {
    classify_logseq_inline_triggers(&item.name, expected, found_reference, found_embed);
    classify_logseq_triggers(
        &item.content,
        expected,
        is_org,
        found_reference,
        found_embed,
    );
    for child in &item.items {
        classify_logseq_list_item_triggers(child, expected, is_org, found_reference, found_embed);
    }
}

fn classify_logseq_inline_triggers(
    inlines: &[lsdoc::ast::Inline],
    expected: &str,
    found_reference: &mut bool,
    found_embed: &mut bool,
) {
    use lsdoc::ast::{Inline, Url};
    for inline in inlines {
        match inline {
            Inline::Link {
                url: Url::BlockRef { v },
                label,
                ..
            } => {
                *found_reference |= v == expected;
                classify_logseq_inline_triggers(label, expected, found_reference, found_embed);
            }
            Inline::Link { label, .. } => {
                classify_logseq_inline_triggers(label, expected, found_reference, found_embed)
            }
            Inline::Macro { name, args, .. } if name == "embed" => {
                *found_embed |= args.first().is_some_and(|argument| {
                    argument
                        .trim()
                        .strip_prefix("((")
                        .and_then(|value| value.strip_suffix("))"))
                        .is_some_and(|value| value == expected)
                });
            }
            Inline::Emphasis { children, .. }
            | Inline::Subscript { children, .. }
            | Inline::Superscript { children, .. }
            | Inline::Tag { children, .. } => {
                classify_logseq_inline_triggers(children, expected, found_reference, found_embed)
            }
            Inline::Fnref { definition, .. } => {
                classify_logseq_inline_triggers(definition, expected, found_reference, found_embed)
            }
            _ => {}
        }
    }
}

fn page_logseq_references(
    path: &ManagedPath,
    preamble: Option<&str>,
    blocks: &[MaterializedBlock],
) -> BTreeSet<LogseqUuid> {
    let is_org = path.as_str().ends_with(".org");
    let mut references = BTreeSet::new();
    if let Some(preamble) = preamble {
        let format = if is_org { "org" } else { "md" };
        references.extend(
            lsdoc::parse_format(preamble, format)
                .refs
                .block
                .into_iter()
                .filter_map(|value| LogseqUuid::parse(&value).ok()),
        );
    }
    for block in blocks {
        references.extend(
            crate::render::block_refs(&block.content, is_org)
                .block
                .into_iter()
                .filter_map(|value| LogseqUuid::parse(&value).ok()),
        );
    }
    references
}

